INSERT INTO `articles` (`id`, `title`, `slug`, `summary`, `content`, `image`, `category`, `is_published`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES ('1', 'Cúm Mùa Mới Nhất: Khuyến Cáo Phòng Ngừa Và Lịch Tiêm Phòng Cho Trẻ Em', 'cum-mua-moi-nhat-khuyen-cao-phong-ngua-va-lich-tiem-phong-cho-tre-em-eGXex', 'Bài viết cung cấp thông tin y khoa chính thống về Cúm Mùa Mới Nhất: Khuyến Cáo Phòng Ngừa Và Lịch Tiêm Phòng Cho Trẻ Em. Đội ngũ bác sĩ chuyên khoa tiêm chủng Medicare khuyến cáo quý khách hàng chủ động tham khảo lịch tiêm và thăm khám kịp thời.', '\n                <p>Tiêm chủng là biện pháp phòng bệnh chủ động, an toàn và hiệu quả nhất được Tổ chức Y tế Thế giới (WHO) và Bộ Y tế Việt Nam khuyến cáo cho mọi lứa tuổi.</p>\n                \n                <h2>1. Tại sao việc tiêm phòng lại quan trọng?</h2>\n                <p>Khi vắc xin đưa vào cơ thể, hệ miễn dịch sẽ được kích hoạt sản sinh ra kháng thể đặc hiệu. Nhờ đó, nếu gặp phải vi khuẩn hoặc vi-rút gây bệnh trong tương lai, cơ thể sẽ có sẵn lá chắn bảo vệ mạnh mẽ, giảm thiểu tối đa nguy cơ biến chứng nặng hoặc tử vong.</p>\n                \n                <p>Chủ động tiêm chủng không chỉ bảo vệ bản thân mà còn tạo nên miễn dịch cộng đồng vững chắc, bảo vệ cho trẻ nhỏ và người cao tuổi xung quanh chúng ta.</p>\n\n                <h2>2. Hướng dẫn chăm sóc và theo dõi sức khỏe</h2>\n                <p>Sau khi tiêm chủng, người tiêm cần ở lại trung tâm theo dõi ít nhất 30 phút để kiểm tra tình trạng sức khỏe ban đầu. Khi về nhà, tiếp tục tự theo dõi trong vòng 24 - 48 giờ tiếp theo. Nếu xuất hiện các triệu chứng như sốt cao kéo dài, co giật hoặc khó thở, cần đến ngay cơ sở y tế gần nhất.</p>\n\n                <h2>3. Đăng ký tư vấn và tiêm chủng tại Medicare Cờ Đỏ</h2>\n                <p>Hệ thống Trung tâm Tiêm chủng Medicare cam kết cung cấp vắc xin chính hãng 100%, bảo quản nghiêm ngặt theo tiêu chuẩn Dây chuyền lạnh GSP (2-8 độ C), quy trình khám sàng lọc miễn phí cùng đội ngũ điều dưỡng giàu kinh nghiệm, nhẹ nhàng.</p>\n            ', 'vaxigrip.jpg', 'Bệnh Truyền Nhiễm', '1', '1', '0', '16702', '2026-05-28 07:17:45', '2026-07-29 07:17:45');
INSERT INTO `articles` (`id`, `title`, `slug`, `summary`, `content`, `image`, `category`, `is_published`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES ('2', 'Bạch Hầu Đang Có Dấu Hiệu Gia Tăng: Cách Nhận Biết Và Tiêm Phòng Kịp Thời', 'bach-hau-dang-co-dau-hieu-gia-tang-cach-nhan-biet-va-tiem-phong-kip-thoi-CsT0k', 'Bài viết cung cấp thông tin y khoa chính thống về Bạch Hầu Đang Có Dấu Hiệu Gia Tăng: Cách Nhận Biết Và Tiêm Phòng Kịp Thời. Đội ngũ bác sĩ chuyên khoa tiêm chủng Medicare khuyến cáo quý khách hàng chủ động tham khảo lịch tiêm và thăm khám kịp thời.', '\n                <p>Tiêm chủng là biện pháp phòng bệnh chủ động, an toàn và hiệu quả nhất được Tổ chức Y tế Thế giới (WHO) và Bộ Y tế Việt Nam khuyến cáo cho mọi lứa tuổi.</p>\n                \n                <h2>1. Tại sao việc tiêm phòng lại quan trọng?</h2>\n                <p>Khi vắc xin đưa vào cơ thể, hệ miễn dịch sẽ được kích hoạt sản sinh ra kháng thể đặc hiệu. Nhờ đó, nếu gặp phải vi khuẩn hoặc vi-rút gây bệnh trong tương lai, cơ thể sẽ có sẵn lá chắn bảo vệ mạnh mẽ, giảm thiểu tối đa nguy cơ biến chứng nặng hoặc tử vong.</p>\n                \n                <p>Chủ động tiêm chủng không chỉ bảo vệ bản thân mà còn tạo nên miễn dịch cộng đồng vững chắc, bảo vệ cho trẻ nhỏ và người cao tuổi xung quanh chúng ta.</p>\n\n                <h2>2. Hướng dẫn chăm sóc và theo dõi sức khỏe</h2>\n                <p>Sau khi tiêm chủng, người tiêm cần ở lại trung tâm theo dõi ít nhất 30 phút để kiểm tra tình trạng sức khỏe ban đầu. Khi về nhà, tiếp tục tự theo dõi trong vòng 24 - 48 giờ tiếp theo. Nếu xuất hiện các triệu chứng như sốt cao kéo dài, co giật hoặc khó thở, cần đến ngay cơ sở y tế gần nhất.</p>\n\n                <h2>3. Đăng ký tư vấn và tiêm chủng tại Medicare Cờ Đỏ</h2>\n                <p>Hệ thống Trung tâm Tiêm chủng Medicare cam kết cung cấp vắc xin chính hãng 100%, bảo quản nghiêm ngặt theo tiêu chuẩn Dây chuyền lạnh GSP (2-8 độ C), quy trình khám sàng lọc miễn phí cùng đội ngũ điều dưỡng giàu kinh nghiệm, nhẹ nhàng.</p>\n            ', 'infanrix.jpg', 'Bệnh Truyền Nhiễm', '1', '1', '0', '15177', '2026-06-22 07:17:45', '2026-07-27 07:17:45');
