INSERT INTO `articles` (`id`, `title`, `slug`, `summary`, `content`, `image`, `category`, `is_published`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES ('10', 'Vắc Xin Phòng Bệnh Phế Cầu 20 Chủng Thế Hệ Mới Đã Có Mặt Tại Medicare', 'vac-xin-phong-benh-phe-cau-20-chung-the-he-moi-da-co-mat-tai-medicare', 'Bài viết cung cấp thông tin y khoa chính thống về Vắc Xin Phòng Bệnh Phế Cầu 20 Chủng Thế Hệ Mới Đã Có Mặt Tại Medicare. Đội ngũ bác sĩ chuyên khoa tiêm chủng Medicare khuyến cáo quý khách hàng chủ động tham khảo lịch tiêm và thăm khám kịp thời.', '<p>Tiêm chủng là biện pháp phòng bệnh chủ động, an toàn và hiệu quả nhất được Tổ chức Y tế Thế giới (WHO) và Bộ Y tế Việt Nam khuyến cáo cho mọi lứa tuổi.</p>\r\n<h2>1. Tại sao việc tiêm phòng lại quan trọng?</h2>\r\n<p>Khi vắc xin đưa vào cơ thể, hệ miễn dịch sẽ được kích hoạt sản sinh ra kháng thể đặc hiệu. Nhờ đó, nếu gặp phải vi khuẩn hoặc vi-rút gây bệnh trong tương lai, cơ thể sẽ có sẵn lá chắn bảo vệ mạnh mẽ, giảm thiểu tối đa nguy cơ biến chứng nặng hoặc tử vong.</p>\r\n<p>Chủ động tiêm chủng không chỉ bảo vệ bản thân mà còn tạo nên miễn dịch cộng đồng vững chắc, bảo vệ cho trẻ nhỏ và người cao tuổi xung quanh chúng ta.</p>\r\n<h2>2. Hướng dẫn chăm sóc và theo dõi sức khỏe</h2>\r\n<p>Sau khi tiêm chủng, người tiêm cần ở lại trung tâm theo dõi ít nhất 30 phút để kiểm tra tình trạng sức khỏe ban đầu. Khi về nhà, tiếp tục tự theo dõi trong vòng 24 - 48 giờ tiếp theo. Nếu xuất hiện các triệu chứng như sốt cao kéo dài, co giật hoặc khó thở, cần đến ngay cơ sở y tế gần nhất.</p>\r\n<h2>3. Đăng ký tư vấn và tiêm chủng tại Medicare </h2>\r\n<p>Hệ thống Trung tâm Tiêm chủng Medicare cam kết cung cấp vắc xin chính hãng 100%, bảo quản nghiêm ngặt theo tiêu chuẩn Dây chuyền lạnh GSP (2-8 độ C), quy trình khám sàng lọc miễn phí cùng đội ngũ điều dưỡng giàu kinh nghiệm, nhẹ nhàng.</p>', 'article_1786439054_6a7ae58e24772.jfif', 'Vắc Xin Mới', '1', '1', '1', '6940', '2026-07-30 07:17:45', '2026-08-11 09:04:14');
INSERT INTO `articles` (`id`, `title`, `slug`, `summary`, `content`, `image`, `category`, `is_published`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES ('11', 'Vắc Xin Ngừa Sốt Xuất Huyết Tỷ Lệ Bảo Vệ Cao Được Cấp Phép Lưu Hành', 'vac-xin-ngua-sot-xuat-huyet-ty-le-bao-ve-cao-duoc-cap-phep-luu-hanh-zJYJm', 'Bài viết cung cấp thông tin y khoa chính thống về Vắc Xin Ngừa Sốt Xuất Huyết Tỷ Lệ Bảo Vệ Cao Được Cấp Phép Lưu Hành. Đội ngũ bác sĩ chuyên khoa tiêm chủng Medicare khuyến cáo quý khách hàng chủ động tham khảo lịch tiêm và thăm khám kịp thời.', '\n                <p>Tiêm chủng là biện pháp phòng bệnh chủ động, an toàn và hiệu quả nhất được Tổ chức Y tế Thế giới (WHO) và Bộ Y tế Việt Nam khuyến cáo cho mọi lứa tuổi.</p>\n                \n                <h2>1. Tại sao việc tiêm phòng lại quan trọng?</h2>\n                <p>Khi vắc xin đưa vào cơ thể, hệ miễn dịch sẽ được kích hoạt sản sinh ra kháng thể đặc hiệu. Nhờ đó, nếu gặp phải vi khuẩn hoặc vi-rút gây bệnh trong tương lai, cơ thể sẽ có sẵn lá chắn bảo vệ mạnh mẽ, giảm thiểu tối đa nguy cơ biến chứng nặng hoặc tử vong.</p>\n                \n                <p>Chủ động tiêm chủng không chỉ bảo vệ bản thân mà còn tạo nên miễn dịch cộng đồng vững chắc, bảo vệ cho trẻ nhỏ và người cao tuổi xung quanh chúng ta.</p>\n\n                <h2>2. Hướng dẫn chăm sóc và theo dõi sức khỏe</h2>\n                <p>Sau khi tiêm chủng, người tiêm cần ở lại trung tâm theo dõi ít nhất 30 phút để kiểm tra tình trạng sức khỏe ban đầu. Khi về nhà, tiếp tục tự theo dõi trong vòng 24 - 48 giờ tiếp theo. Nếu xuất hiện các triệu chứng như sốt cao kéo dài, co giật hoặc khó thở, cần đến ngay cơ sở y tế gần nhất.</p>\n\n                <h2>3. Đăng ký tư vấn và tiêm chủng tại Medicare Cờ Đỏ</h2>\n                <p>Hệ thống Trung tâm Tiêm chủng Medicare cam kết cung cấp vắc xin chính hãng 100%, bảo quản nghiêm ngặt theo tiêu chuẩn Dây chuyền lạnh GSP (2-8 độ C), quy trình khám sàng lọc miễn phí cùng đội ngũ điều dưỡng giàu kinh nghiệm, nhẹ nhàng.</p>\n            ', 'priorix.jpg', 'Vắc Xin Mới', '1', '1', '0', '10785', '2026-05-17 07:17:45', '2026-08-05 07:17:45');
INSERT INTO `articles` (`id`, `title`, `slug`, `summary`, `content`, `image`, `category`, `is_published`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES ('12', 'Vắc Xin 6 Trong 1 Hexaxim Pháp Thế Hệ Mới Tiết Kiệm Thời Gian Cho Bé', 'vac-xin-6-trong-1-hexaxim-phap-the-he-moi-tiet-kiem-thoi-gian-cho-be-fpfTh', 'Bài viết cung cấp thông tin y khoa chính thống về Vắc Xin 6 Trong 1 Hexaxim Pháp Thế Hệ Mới Tiết Kiệm Thời Gian Cho Bé. Đội ngũ bác sĩ chuyên khoa tiêm chủng Medicare khuyến cáo quý khách hàng chủ động tham khảo lịch tiêm và thăm khám kịp thời.', '\n                <p>Tiêm chủng là biện pháp phòng bệnh chủ động, an toàn và hiệu quả nhất được Tổ chức Y tế Thế giới (WHO) và Bộ Y tế Việt Nam khuyến cáo cho mọi lứa tuổi.</p>\n                \n                <h2>1. Tại sao việc tiêm phòng lại quan trọng?</h2>\n                <p>Khi vắc xin đưa vào cơ thể, hệ miễn dịch sẽ được kích hoạt sản sinh ra kháng thể đặc hiệu. Nhờ đó, nếu gặp phải vi khuẩn hoặc vi-rút gây bệnh trong tương lai, cơ thể sẽ có sẵn lá chắn bảo vệ mạnh mẽ, giảm thiểu tối đa nguy cơ biến chứng nặng hoặc tử vong.</p>\n                \n                <p>Chủ động tiêm chủng không chỉ bảo vệ bản thân mà còn tạo nên miễn dịch cộng đồng vững chắc, bảo vệ cho trẻ nhỏ và người cao tuổi xung quanh chúng ta.</p>\n\n                <h2>2. Hướng dẫn chăm sóc và theo dõi sức khỏe</h2>\n                <p>Sau khi tiêm chủng, người tiêm cần ở lại trung tâm theo dõi ít nhất 30 phút để kiểm tra tình trạng sức khỏe ban đầu. Khi về nhà, tiếp tục tự theo dõi trong vòng 24 - 48 giờ tiếp theo. Nếu xuất hiện các triệu chứng như sốt cao kéo dài, co giật hoặc khó thở, cần đến ngay cơ sở y tế gần nhất.</p>\n\n                <h2>3. Đăng ký tư vấn và tiêm chủng tại Medicare Cờ Đỏ</h2>\n                <p>Hệ thống Trung tâm Tiêm chủng Medicare cam kết cung cấp vắc xin chính hãng 100%, bảo quản nghiêm ngặt theo tiêu chuẩn Dây chuyền lạnh GSP (2-8 độ C), quy trình khám sàng lọc miễn phí cùng đội ngũ điều dưỡng giàu kinh nghiệm, nhẹ nhàng.</p>\n            ', 'hexaxim.jpg', 'Vắc Xin Mới', '1', '1', '0', '11494', '2026-06-10 07:17:45', '2026-07-01 07:17:45');
