INSERT INTO `articles` (`id`, `title`, `slug`, `summary`, `content`, `image`, `category`, `is_published`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES ('21', 'Ho Gà Ở Trẻ Sơ Sinh: Mối Nguy Hồi Từ Các Cơn Ho Co Thắt Vùng Cổ Họng (Phần 21)', 'ho-ga-o-tre-so-sinh-moi-nguy-hoi-tu-cac-con-ho-co-that-vung-co-hong-phan-21-Azgvz', 'Bài viết cung cấp thông tin y khoa chính thống về Ho Gà Ở Trẻ Sơ Sinh: Mối Nguy Hồi Từ Các Cơn Ho Co Thắt Vùng Cổ Họng (Phần 21). Đội ngũ bác sĩ chuyên khoa tiêm chủng Medicare khuyến cáo quý khách hàng chủ động tham khảo lịch tiêm và thăm khám kịp thời.', '\n                <p>Tiêm chủng là biện pháp phòng bệnh chủ động, an toàn và hiệu quả nhất được Tổ chức Y tế Thế giới (WHO) và Bộ Y tế Việt Nam khuyến cáo cho mọi lứa tuổi.</p>\n                \n                <h2>1. Tại sao việc tiêm phòng lại quan trọng?</h2>\n                <p>Khi vắc xin đưa vào cơ thể, hệ miễn dịch sẽ được kích hoạt sản sinh ra kháng thể đặc hiệu. Nhờ đó, nếu gặp phải vi khuẩn hoặc vi-rút gây bệnh trong tương lai, cơ thể sẽ có sẵn lá chắn bảo vệ mạnh mẽ, giảm thiểu tối đa nguy cơ biến chứng nặng hoặc tử vong.</p>\n                \n                <p>Chủ động tiêm chủng không chỉ bảo vệ bản thân mà còn tạo nên miễn dịch cộng đồng vững chắc, bảo vệ cho trẻ nhỏ và người cao tuổi xung quanh chúng ta.</p>\n\n                <h2>2. Hướng dẫn chăm sóc và theo dõi sức khỏe</h2>\n                <p>Sau khi tiêm chủng, người tiêm cần ở lại trung tâm theo dõi ít nhất 30 phút để kiểm tra tình trạng sức khỏe ban đầu. Khi về nhà, tiếp tục tự theo dõi trong vòng 24 - 48 giờ tiếp theo. Nếu xuất hiện các triệu chứng như sốt cao kéo dài, co giật hoặc khó thở, cần đến ngay cơ sở y tế gần nhất.</p>\n\n                <h2>3. Đăng ký tư vấn và tiêm chủng tại Medicare Cờ Đỏ</h2>\n                <p>Hệ thống Trung tâm Tiêm chủng Medicare cam kết cung cấp vắc xin chính hãng 100%, bảo quản nghiêm ngặt theo tiêu chuẩn Dây chuyền lạnh GSP (2-8 độ C), quy trình khám sàng lọc miễn phí cùng đội ngũ điều dưỡng giàu kinh nghiệm, nhẹ nhàng.</p>\n            ', 'rotarix.jpg', 'Bệnh Truyền Nhiễm', '1', '1', '0', '543', '2026-05-21 07:17:45', '2026-08-02 07:17:45');
INSERT INTO `articles` (`id`, `title`, `slug`, `summary`, `content`, `image`, `category`, `is_published`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES ('22', 'Hướng Dẫn Chi Tiết Theo Dõi Phản Ứng Sau Tiêm Chủng Tại Nhà Cho Trẻ (Phần 22)', 'huong-dan-chi-tiet-theo-doi-phan-ung-sau-tiem-chung-tai-nha-cho-tre-phan-22-H06JP', 'Bài viết cung cấp thông tin y khoa chính thống về Hướng Dẫn Chi Tiết Theo Dõi Phản Ứng Sau Tiêm Chủng Tại Nhà Cho Trẻ (Phần 22). Đội ngũ bác sĩ chuyên khoa tiêm chủng Medicare khuyến cáo quý khách hàng chủ động tham khảo lịch tiêm và thăm khám kịp thời.', '\n                <p>Tiêm chủng là biện pháp phòng bệnh chủ động, an toàn và hiệu quả nhất được Tổ chức Y tế Thế giới (WHO) và Bộ Y tế Việt Nam khuyến cáo cho mọi lứa tuổi.</p>\n                \n                <h2>1. Tại sao việc tiêm phòng lại quan trọng?</h2>\n                <p>Khi vắc xin đưa vào cơ thể, hệ miễn dịch sẽ được kích hoạt sản sinh ra kháng thể đặc hiệu. Nhờ đó, nếu gặp phải vi khuẩn hoặc vi-rút gây bệnh trong tương lai, cơ thể sẽ có sẵn lá chắn bảo vệ mạnh mẽ, giảm thiểu tối đa nguy cơ biến chứng nặng hoặc tử vong.</p>\n                \n                <p>Chủ động tiêm chủng không chỉ bảo vệ bản thân mà còn tạo nên miễn dịch cộng đồng vững chắc, bảo vệ cho trẻ nhỏ và người cao tuổi xung quanh chúng ta.</p>\n\n                <h2>2. Hướng dẫn chăm sóc và theo dõi sức khỏe</h2>\n                <p>Sau khi tiêm chủng, người tiêm cần ở lại trung tâm theo dõi ít nhất 30 phút để kiểm tra tình trạng sức khỏe ban đầu. Khi về nhà, tiếp tục tự theo dõi trong vòng 24 - 48 giờ tiếp theo. Nếu xuất hiện các triệu chứng như sốt cao kéo dài, co giật hoặc khó thở, cần đến ngay cơ sở y tế gần nhất.</p>\n\n                <h2>3. Đăng ký tư vấn và tiêm chủng tại Medicare Cờ Đỏ</h2>\n                <p>Hệ thống Trung tâm Tiêm chủng Medicare cam kết cung cấp vắc xin chính hãng 100%, bảo quản nghiêm ngặt theo tiêu chuẩn Dây chuyền lạnh GSP (2-8 độ C), quy trình khám sàng lọc miễn phí cùng đội ngũ điều dưỡng giàu kinh nghiệm, nhẹ nhàng.</p>\n            ', 'hexaxim.jpg', 'Khuyến Cáo Y Tế', '1', '1', '0', '5215', '2026-05-20 07:17:45', '2026-05-30 07:17:45');
