INSERT INTO `articles` (`id`, `title`, `slug`, `summary`, `content`, `image`, `category`, `is_published`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES ('96', 'Quy Trình Khám Sàng Lọc Trước Tiêm Theo Tiêu Chuẩn Quốc Tế Tại Medicare (Phần 96)', 'quy-trinh-kham-sang-loc-truoc-tiem-theo-tieu-chuan-quoc-te-tai-medicare-phan-96-B5dbv', 'Bài viết cung cấp thông tin y khoa chính thống về Quy Trình Khám Sàng Lọc Trước Tiêm Theo Tiêu Chuẩn Quốc Tế Tại Medicare (Phần 96). Đội ngũ bác sĩ chuyên khoa tiêm chủng Medicare khuyến cáo quý khách hàng chủ động tham khảo lịch tiêm và thăm khám kịp thời.', '\n                <p>Tiêm chủng là biện pháp phòng bệnh chủ động, an toàn và hiệu quả nhất được Tổ chức Y tế Thế giới (WHO) và Bộ Y tế Việt Nam khuyến cáo cho mọi lứa tuổi.</p>\n                \n                <h2>1. Tại sao việc tiêm phòng lại quan trọng?</h2>\n                <p>Khi vắc xin đưa vào cơ thể, hệ miễn dịch sẽ được kích hoạt sản sinh ra kháng thể đặc hiệu. Nhờ đó, nếu gặp phải vi khuẩn hoặc vi-rút gây bệnh trong tương lai, cơ thể sẽ có sẵn lá chắn bảo vệ mạnh mẽ, giảm thiểu tối đa nguy cơ biến chứng nặng hoặc tử vong.</p>\n                \n                <p>Chủ động tiêm chủng không chỉ bảo vệ bản thân mà còn tạo nên miễn dịch cộng đồng vững chắc, bảo vệ cho trẻ nhỏ và người cao tuổi xung quanh chúng ta.</p>\n\n                <h2>2. Hướng dẫn chăm sóc và theo dõi sức khỏe</h2>\n                <p>Sau khi tiêm chủng, người tiêm cần ở lại trung tâm theo dõi ít nhất 30 phút để kiểm tra tình trạng sức khỏe ban đầu. Khi về nhà, tiếp tục tự theo dõi trong vòng 24 - 48 giờ tiếp theo. Nếu xuất hiện các triệu chứng như sốt cao kéo dài, co giật hoặc khó thở, cần đến ngay cơ sở y tế gần nhất.</p>\n\n                <h2>3. Đăng ký tư vấn và tiêm chủng tại Medicare Cờ Đỏ</h2>\n                <p>Hệ thống Trung tâm Tiêm chủng Medicare cam kết cung cấp vắc xin chính hãng 100%, bảo quản nghiêm ngặt theo tiêu chuẩn Dây chuyền lạnh GSP (2-8 độ C), quy trình khám sàng lọc miễn phí cùng đội ngũ điều dưỡng giàu kinh nghiệm, nhẹ nhàng.</p>\n            ', 'verorab.jpg', 'Khuyến Cáo Y Tế', '1', '1', '0', '7934', '2026-07-02 07:17:46', '2026-06-28 07:17:46');
INSERT INTO `articles` (`id`, `title`, `slug`, `summary`, `content`, `image`, `category`, `is_published`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES ('97', 'Hội Nghị Y Học Tiêm Chủng Việt Nam: Ra Mắt Phác Đồ Tiêm Phòng Thế Hệ Mới (Phần 97)', 'hoi-nghi-y-hoc-tiem-chung-viet-nam-ra-mat-phac-do-tiem-phong-the-he-moi-phan-97-13lA9', 'Bài viết cung cấp thông tin y khoa chính thống về Hội Nghị Y Học Tiêm Chủng Việt Nam: Ra Mắt Phác Đồ Tiêm Phòng Thế Hệ Mới (Phần 97). Đội ngũ bác sĩ chuyên khoa tiêm chủng Medicare khuyến cáo quý khách hàng chủ động tham khảo lịch tiêm và thăm khám kịp thời.', '\n                <p>Tiêm chủng là biện pháp phòng bệnh chủ động, an toàn và hiệu quả nhất được Tổ chức Y tế Thế giới (WHO) và Bộ Y tế Việt Nam khuyến cáo cho mọi lứa tuổi.</p>\n                \n                <h2>1. Tại sao việc tiêm phòng lại quan trọng?</h2>\n                <p>Khi vắc xin đưa vào cơ thể, hệ miễn dịch sẽ được kích hoạt sản sinh ra kháng thể đặc hiệu. Nhờ đó, nếu gặp phải vi khuẩn hoặc vi-rút gây bệnh trong tương lai, cơ thể sẽ có sẵn lá chắn bảo vệ mạnh mẽ, giảm thiểu tối đa nguy cơ biến chứng nặng hoặc tử vong.</p>\n                \n                <p>Chủ động tiêm chủng không chỉ bảo vệ bản thân mà còn tạo nên miễn dịch cộng đồng vững chắc, bảo vệ cho trẻ nhỏ và người cao tuổi xung quanh chúng ta.</p>\n\n                <h2>2. Hướng dẫn chăm sóc và theo dõi sức khỏe</h2>\n                <p>Sau khi tiêm chủng, người tiêm cần ở lại trung tâm theo dõi ít nhất 30 phút để kiểm tra tình trạng sức khỏe ban đầu. Khi về nhà, tiếp tục tự theo dõi trong vòng 24 - 48 giờ tiếp theo. Nếu xuất hiện các triệu chứng như sốt cao kéo dài, co giật hoặc khó thở, cần đến ngay cơ sở y tế gần nhất.</p>\n\n                <h2>3. Đăng ký tư vấn và tiêm chủng tại Medicare Cờ Đỏ</h2>\n                <p>Hệ thống Trung tâm Tiêm chủng Medicare cam kết cung cấp vắc xin chính hãng 100%, bảo quản nghiêm ngặt theo tiêu chuẩn Dây chuyền lạnh GSP (2-8 độ C), quy trình khám sàng lọc miễn phí cùng đội ngũ điều dưỡng giàu kinh nghiệm, nhẹ nhàng.</p>\n            ', 'vaxigrip.jpg', 'Tin Nóng Y Học', '1', '1', '0', '3898', '2026-07-16 07:17:46', '2026-08-12 15:12:21');
