INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('9', 'about_hero_title', 'Giới Thiệu Hệ Thống Tiêm Chủng Medicare', '2026-08-07 07:17:44', '2026-08-07 07:17:44');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('10', 'about_hero_desc', 'Đơn vị y tế uy tín hàng đầu cung cấp giải pháp phòng bệnh toàn diện bằng vắc xin chất lượng cao cho trẻ em và người lớn tại Cần Thơ.', '2026-08-07 07:17:44', '2026-08-07 07:17:44');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('11', 'about_story_title', 'Hành trình Bảo vệ Sức khỏe Cộng đồng', '2026-08-07 07:17:44', '2026-08-07 07:17:44');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('12', 'about_story_desc', 'Được thành lập từ năm 2016, Medicare bắt đầu với sứ mệnh mang dịch vụ tiêm chủng an toàn, chất lượng cao và chi phí hợp lý đến gần hơn với người dân tại các huyện ngoại thành Cần Thơ như Cờ Đỏ và Thới Lai. Trải qua gần 10 năm phát triển, chúng tôi tự hào trở thành điểm tựa sức khỏe đáng tin cậy cho hàng chục ngàn gia đình, liên tục cải tiến chất lượng và nâng cao dịch vụ chăm sóc y tế.', '2026-08-07 07:17:44', '2026-08-07 07:17:44');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('13', 'about_stat_exp', '10+', '2026-08-07 07:17:44', '2026-08-07 07:17:44');
