INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('16', 'about_stat_clients_lbl', 'Khách Hàng Hài Lòng', '2026-08-07 07:17:44', '2026-08-07 07:17:44');
