INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('19', 'about_mission_title', 'Sứ Mệnh Của Chúng Tôi', '2026-08-07 07:17:44', '2026-08-07 07:17:44');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('20', 'about_mission_desc', 'Mang lại dịch vụ tiêm chủng an toàn tuyệt đối, vaccine chính hãng chất lượng cao với chi phí hợp lý cho mọi gia đình. Giúp cộng đồng chủ động phòng bệnh truyền nhiễm nguy hiểm.', '2026-08-07 07:17:44', '2026-08-07 07:17:44');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('21', 'about_vision_title', 'Tầm Nhìn Phát Triển', '2026-08-07 07:17:44', '2026-08-07 07:17:44');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('22', 'about_vision_desc', 'Trở thành hệ thống tiêm chủng dịch vụ uy tín hàng đầu Cần Thơ và Đồng bằng sông Cửu Long, không ngừng cải tiến trang thiết bị và ứng dụng sổ tiêm điện tử thông minh.', '2026-08-07 07:17:44', '2026-08-07 07:17:44');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('23', 'about_values_desc', 'Mọi hoạt động y tế của hệ thống tiêm chủng Medicare đều tuân thủ các chuẩn mực chất lượng khắt khe nhất để bảo vệ an toàn cho sức khỏe gia đình bạn.', '2026-08-07 07:17:44', '2026-08-07 07:17:44');
