INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('26', 'about_val1_desc', 'Quy trình tiêm chủng an toàn 5 bước chuẩn Bộ Y tế, 100% bác sĩ khám sàng lọc cẩn thận trước tiêm và theo dõi chặt chẽ sau tiêm.', '2026-08-07 07:17:44', '2026-08-07 07:17:44');
