INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('29', 'about_val2_desc', 'Cam kết vắc xin nhập khẩu chính hãng từ các tập đoàn dược phẩm lớn trên thế giới như GSK, MSD, Sanofi Pasteur, Pfizer.', '2026-08-07 07:17:45', '2026-08-07 07:17:45');
