INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('75', 'home_safe_process_desc', 'Medicare áp dụng quy trình tiêm chủng an toàn nghiêm ngặt chuẩn Bộ Y tế để bảo vệ sức khỏe của bạn.', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
