INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('77', 'home_safe_process', '[{\"step\":\"1\",\"title\":\"Khám Sàng Lọc\",\"desc\":\"100% khách hàng được bác sĩ chuyên khoa khám sàng lọc chỉ định tiêm chủng phù hợp.\"},{\"step\":\"2\",\"title\":\"Tư Vấn & Chỉ Định\",\"desc\":\"Bác sĩ giải thích tác dụng, phản ứng phụ và thống nhất vắc xin trước khi tiêm.\"},{\"step\":\"3\",\"title\":\"Thực Hiện Tiêm\",\"desc\":\"Điều dưỡng đối chiếu thông tin vắc xin và thực hiện tiêm chủng nhẹ nhàng, đúng kỹ thuật.\"},{\"step\":\"4\",\"title\":\"Theo Dõi Sau Tiêm\",\"desc\":\"Theo dõi sức khỏe tại khu vực sảnh chờ 30 phút để phát hiện sớm phản ứng bất thường.\"},{\"step\":\"5\",\"title\":\"Kiểm Tra & Ra Về\",\"desc\":\"Bác sĩ kiểm tra lại vết tiêm, tư vấn cách theo dõi chăm sóc tại nhà trước khi về.\"}]', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('78', 'home_safe_process_draft', '[{\"step\":\"1\",\"title\":\"Khám Sàng Lọc\",\"desc\":\"100% khách hàng được bác sĩ chuyên khoa khám sàng lọc chỉ định tiêm chủng phù hợp.\"},{\"step\":\"2\",\"title\":\"Tư Vấn & Chỉ Định\",\"desc\":\"Bác sĩ giải thích tác dụng, phản ứng phụ và thống nhất vắc xin trước khi tiêm.\"},{\"step\":\"3\",\"title\":\"Thực Hiện Tiêm\",\"desc\":\"Điều dưỡng đối chiếu thông tin vắc xin và thực hiện tiêm chủng nhẹ nhàng, đúng kỹ thuật.\"},{\"step\":\"4\",\"title\":\"Theo Dõi Sau Tiêm\",\"desc\":\"Theo dõi sức khỏe tại khu vực sảnh chờ 30 phút để phát hiện sớm phản ứng bất thường.\"},{\"step\":\"5\",\"title\":\"Kiểm Tra & Ra Về\",\"desc\":\"Bác sĩ kiểm tra lại vết tiêm, tư vấn cách theo dõi chăm sóc tại nhà trước khi về.\"}]', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('79', 'home_testimonials', '[{\"name\":\"Chị Nguyễn Thảo Vy\",\"role\":\"Phụ huynh bé Min (3 tháng)\",\"content\":\"Phòng tiêm sạch sẽ, y bác sĩ rất nhẹ nhàng và chu đáo. Bé nhà mình tiêm về không hề bị sốt. Rất an tâm!\",\"avatar\":\"/images/logo.png\"},{\"name\":\"Anh Trần Quốc Bảo\",\"role\":\"Khách hàng tại Cờ Đỏ\",\"content\":\"Quy trình tiêm chủng chuyên nghiệp, đặt lịch online trước đến là được vào khám ngay không cần chờ đợi.\",\"avatar\":\"/images/logo.png\"}]', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('80', 'home_testimonials_draft', '[{\"name\":\"Chị Nguyễn Thảo Vy\",\"role\":\"Phụ huynh bé Min (3 tháng)\",\"content\":\"Phòng tiêm sạch sẽ, y bác sĩ rất nhẹ nhàng và chu đáo. Bé nhà mình tiêm về không hề bị sốt. Rất an tâm!\",\"avatar\":\"/images/logo.png\"},{\"name\":\"Anh Trần Quốc Bảo\",\"role\":\"Khách hàng tại Cờ Đỏ\",\"content\":\"Quy trình tiêm chủng chuyên nghiệp, đặt lịch online trước đến là được vào khám ngay không cần chờ đợi.\",\"avatar\":\"/images/logo.png\"}]', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('81', 'home_faq_title', 'Câu Hỏi Thường Gặp', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('82', 'home_faq_title_draft', 'Câu Hỏi Thường Gặp', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('83', 'home_faq_desc', 'Giải đáp những thắc mắc phổ biến nhất về dịch vụ tiêm chủng tại Medicare.', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('84', 'home_faq_desc_draft', 'Giải đáp những thắc mắc phổ biến nhất về dịch vụ tiêm chủng tại Medicare.', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('85', 'home_faqs', '[{\"q\":\"Trẻ bao nhiêu tháng tuổi bắt đầu tiêm chủng?\",\"a\":\"Trẻ sơ sinh nên được tiêm mũi đầu tiên (Viêm Gan B) ngay trong 24 giờ sau sinh. Từ 2 tháng tuổi, bé sẽ bắt đầu các mũi tiêm cơ bản như 6in1, Rotavirus, Phế cầu.\"},{\"q\":\"Tiêm vắc xin có tác dụng phụ không?\",\"a\":\"Phản ứng nhẹ như sưng đỏ tại chỗ tiêm, sốt nhẹ trong 1-2 ngày là bình thường. Tại Medicare, bé được theo dõi 30 phút sau tiêm và được hướng dẫn chi tiết cách chăm sóc tại nhà.\"},{\"q\":\"Giá vắc xin có bao gồm phí khám sàng lọc không?\",\"a\":\"Phí khám sàng lọc trước tiêm tại Medicare là hoàn toàn MIỄN PHÍ. Giá niêm yết trên website đã bao gồm trọn gói dịch vụ.\"}]', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('86', 'home_faqs_draft', '[{\"q\":\"Trẻ bao nhiêu tháng tuổi bắt đầu tiêm chủng?\",\"a\":\"Trẻ sơ sinh nên được tiêm mũi đầu tiên (Viêm Gan B) ngay trong 24 giờ sau sinh. Từ 2 tháng tuổi, bé sẽ bắt đầu các mũi tiêm cơ bản như 6in1, Rotavirus, Phế cầu.\"},{\"q\":\"Tiêm vắc xin có tác dụng phụ không?\",\"a\":\"Phản ứng nhẹ như sưng đỏ tại chỗ tiêm, sốt nhẹ trong 1-2 ngày là bình thường. Tại Medicare, bé được theo dõi 30 phút sau tiêm và được hướng dẫn chi tiết cách chăm sóc tại nhà.\"},{\"q\":\"Giá vắc xin có bao gồm phí khám sàng lọc không?\",\"a\":\"Phí khám sàng lọc trước tiêm tại Medicare là hoàn toàn MIỄN PHÍ. Giá niêm yết trên website đã bao gồm trọn gói dịch vụ.\"}]', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('87', 'about_hero_title_draft', 'Giới Thiệu Hệ Thống Tiêm Chủng Medicare', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('88', 'about_hero_desc_draft', 'Đơn vị y tế uy tín hàng đầu cung cấp giải pháp phòng bệnh toàn diện bằng vắc xin chất lượng cao cho trẻ em và người lớn tại Cần Thơ.', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('89', 'about_story_title_draft', 'Hành trình Bảo vệ Sức khỏe Cộng đồng', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('90', 'about_story_desc_draft', 'Được thành lập từ năm 2016, Medicare bắt đầu với sứ mệnh mang dịch vụ tiêm chủng an toàn, chất lượng cao và chi phí hợp lý đến gần hơn với người dân tại các huyện ngoại thành Cần Thơ như Cờ Đỏ và Thới Lai. Trải qua gần 10 năm phát triển, chúng tôi tự hào trở thành điểm tựa sức khỏe đáng tin cậy cho hàng chục ngàn gia đình, liên tục cải tiến chất lượng và nâng cao dịch vụ chăm sóc y tế.', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('91', 'about_stat_exp_draft', '10+', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('92', 'about_stat_exp_lbl_draft', 'Năm Kinh Nghiệm', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('93', 'about_stat_clients_draft', '50,000+', '2026-08-12 17:17:13', '2026-08-12 17:17:13');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('94', 'about_stat_clients_lbl_draft', 'Khách Hàng Hài Lòng', '2026-08-12 17:17:14', '2026-08-12 17:17:14');
