INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('97', 'about_mission_title_draft', 'Sứ Mệnh Của Chúng Tôi', '2026-08-12 17:17:14', '2026-08-12 17:17:14');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('98', 'about_mission_desc_draft', 'Mang lại dịch vụ tiêm chủng an toàn tuyệt đối, vaccine chính hãng chất lượng cao với chi phí hợp lý cho mọi gia đình. Giúp cộng đồng chủ động phòng bệnh truyền nhiễm nguy hiểm.', '2026-08-12 17:17:14', '2026-08-12 17:17:14');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('99', 'about_vision_title_draft', 'Tầm Nhìn Phát Triển', '2026-08-12 17:17:14', '2026-08-12 17:17:14');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('100', 'about_vision_desc_draft', 'Trở thành hệ thống tiêm chủng dịch vụ uy tín hàng đầu Cần Thơ và Đồng bằng sông Cửu Long, không ngừng cải tiến trang thiết bị và ứng dụng sổ tiêm điện tử thông minh.', '2026-08-12 17:17:14', '2026-08-12 17:17:14');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('101', 'about_values_desc_draft', 'Mọi hoạt động y tế của hệ thống tiêm chủng Medicare đều tuân thủ các chuẩn mực chất lượng khắt khe nhất để bảo vệ an toàn cho sức khỏe gia đình bạn.', '2026-08-12 17:17:14', '2026-08-12 17:17:14');
