INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('123', 'services_hero_desc', 'Cung cấp đầy đủ gói tiêm vắc xin cho Trẻ em, Người lớn, Phụ nữ chuẩn bị mang thai và Tiêm chủng lưu động doanh nghiệp với chuẩn an toàn y tế tốt nhất.', '2026-08-12 17:17:14', '2026-08-12 17:17:14');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('124', 'services_hero_desc_draft', 'Cung cấp đầy đủ gói tiêm vắc xin cho Trẻ em, Người lớn, Phụ nữ chuẩn bị mang thai và Tiêm chủng lưu động doanh nghiệp với chuẩn an toàn y tế tốt nhất.', '2026-08-12 17:17:14', '2026-08-12 17:17:14');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('125', 'services_list', '[{\"title\":\"Tiêm vắc xin lẻ\",\"desc\":\"Cung cấp đầy đủ các loại vắc xin lẻ chất lượng cao cho trẻ em và người lớn. Khách hàng lựa chọn tiêm theo nhu cầu sau khi khám sàng lọc.\",\"icon\":\"syringe\"},{\"title\":\"Gói vắc xin toàn diện\",\"desc\":\"Thiết kế sẵn các gói vắc xin theo từng độ tuổi (0-6 tháng, 0-12 tháng, phụ nữ mang thai) giúp bảo vệ toàn diện, giữ giá và giữ đủ vắc xin trong cả liệu trình.\",\"icon\":\"package\"},{\"title\":\"Tiêm chủng theo yêu cầu\",\"desc\":\"Dịch vụ đặt trước vắc xin khan hiếm, bảo quản và giữ riêng vắc xin cho bé của bạn theo đúng thời hạn lịch hẹn.\",\"icon\":\"calendar-check\"},{\"title\":\"Tiêm chủng lưu động\",\"desc\":\"Hỗ trợ các cơ quan, trường học, doanh nghiệp thực hiện tiêm chủng tập trung cho học sinh, nhân viên tại thực địa an toàn và nhanh chóng.\",\"icon\":\"truck\"}]', '2026-08-12 17:17:14', '2026-08-12 17:17:14');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('126', 'services_list_draft', '[{\"title\":\"Tiêm vắc xin lẻ\",\"desc\":\"Cung cấp đầy đủ các loại vắc xin lẻ chất lượng cao cho trẻ em và người lớn. Khách hàng lựa chọn tiêm theo nhu cầu sau khi khám sàng lọc.\",\"icon\":\"syringe\"},{\"title\":\"Gói vắc xin toàn diện\",\"desc\":\"Thiết kế sẵn các gói vắc xin theo từng độ tuổi (0-6 tháng, 0-12 tháng, phụ nữ mang thai) giúp bảo vệ toàn diện, giữ giá và giữ đủ vắc xin trong cả liệu trình.\",\"icon\":\"package\"},{\"title\":\"Tiêm chủng theo yêu cầu\",\"desc\":\"Dịch vụ đặt trước vắc xin khan hiếm, bảo quản và giữ riêng vắc xin cho bé của bạn theo đúng thời hạn lịch hẹn.\",\"icon\":\"calendar-check\"},{\"title\":\"Tiêm chủng lưu động\",\"desc\":\"Hỗ trợ các cơ quan, trường học, doanh nghiệp thực hiện tiêm chủng tập trung cho học sinh, nhân viên tại thực địa an toàn và nhanh chóng.\",\"icon\":\"truck\"}]', '2026-08-12 17:17:14', '2026-08-12 17:17:14');
INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('127', 'services_promos', '[{\"title\":\"Miễn phí khám sàng lọc\",\"desc\":\"100% khách hàng đến Medicare đều được bác sĩ khám sàng lọc và tư vấn kỹ lưỡng hoàn toàn miễn phí.\"},{\"title\":\"Ưu đãi mua theo gói\",\"desc\":\"Tiết kiệm lên tới 5 - 10% chi phí so với mua lẻ, hỗ trợ trả góp lãi suất 0% giúp giảm nhẹ gánh nặng tài chính.\"}]', '2026-08-12 17:17:14', '2026-08-12 17:17:14');
