INSERT INTO `settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES ('129', 'services_commitments', '[{\"title\":\"100% Vắc xin chính hãng\",\"desc\":\"Vắc xin được nhập khẩu trực tiếp từ các hãng sản xuất dược phẩm uy tín toàn cầu (GSK, Sanofi Pasteur, MSD, Pfizer...)\"},{\"title\":\"Bảo quản lạnh GSP\",\"desc\":\"Hệ thống kho lạnh trung tâm đạt chuẩn bảo quản nghiêm ngặt từ 2 - 8°C với hệ thống giám sát nhiệt độ tự động 24/7.\"},{\"title\":\"Đội ngũ tận tâm chuyên nghiệp\",\"desc\":\"Y bác sĩ có chứng chỉ an toàn tiêm chủng, điều dưỡng thao tác tiêm nhẹ nhàng, thấu hiểu tâm lý trẻ em.\"}]', '2026-08-12 17:17:14', '2026-08-12 17:17:14');
