INSERT INTO `vaccines` (`id`, `name`, `price`, `sale_price`, `doses`, `stock_status`, `description`, `disease_prevention`, `category`, `age_group`, `origin`, `manufacturer`, `dosage`, `administration_route`, `detailed_schedule`, `contraindications`, `adverse_effects`, `warnings`, `source_reference_url`, `source_review_date`, `image`, `is_featured`, `sort_order`, `views`, `is_active`, `created_at`, `updated_at`) VALUES ('1', 'Hexaxim', '1000000', NULL, '1', 'available', 'Vắc xin 6in1 phòng 6 bệnh truyền nhiễm nguy hiểm: Bạch hầu – Ho gà – Uốn ván – Bại liệt – Viêm gan B – Hib.', 'Phòng 6 bệnh nguy hiểm', 'Vắc xin 6 trong 1', 'Trẻ từ 2 tháng tuổi', 'Pháp', 'Sanofi Pasteur', '0.5ml', 'Tiêm bắp.', 'Từ 6 tuần tuổi: lịch cơ bản 2 hoặc 3 liều; khoảng cách và liều nhắc thực hiện theo hướng dẫn sản phẩm và chương trình tiêm chủng áp dụng.', 'Quá mẫn với thành phần hoặc liều trước; bệnh não không rõ nguyên nhân sau vắc xin chứa ho gà.', 'Đau, đỏ, sưng chỗ tiêm; sốt, quấy khóc, buồn ngủ hoặc giảm ăn.', 'Hoãn khi sốt hoặc nhiễm trùng cấp vừa đến nặng; cần sẵn sàng xử trí phản vệ.', 'https://extranet.who.int/prequal/sites/default/files/vwa_vaccine/FVP-P-285_Hexaxim_1dose_SanofiW_PI-2025.pdf', '2026-08-10', '1-hexaxim.jpg', '1', '1', '3', '1', '2026-08-07 07:17:38', '2026-08-12 16:15:57');
INSERT INTO `vaccines` (`id`, `name`, `price`, `sale_price`, `doses`, `stock_status`, `description`, `disease_prevention`, `category`, `age_group`, `origin`, `manufacturer`, `dosage`, `administration_route`, `detailed_schedule`, `contraindications`, `adverse_effects`, `warnings`, `source_reference_url`, `source_review_date`, `image`, `is_featured`, `sort_order`, `views`, `is_active`, `created_at`, `updated_at`) VALUES ('2', 'Infanrix Hexa', '1050000', '1050000', '3', 'available', 'Vắc xin 6in1 kết hợp phòng Bạch hầu, Ho gà, Uốn ván, Bại liệt, Viêm gan B và các bệnh do vi khuẩn Hib.', 'Bạch hầu, Ho gà, Uốn ván, Bại liệt, Viêm gan B, Hib', 'Vắc xin 6 trong 1', 'Trẻ em (6 tuần – 24 tháng)', 'Bỉ', 'GSK', '0.5ml', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2-infanrix-hexa.jfif', '0', '2', '7', '1', '2026-08-07 07:17:38', '2026-08-12 15:46:52');
INSERT INTO `vaccines` (`id`, `name`, `price`, `sale_price`, `doses`, `stock_status`, `description`, `disease_prevention`, `category`, `age_group`, `origin`, `manufacturer`, `dosage`, `administration_route`, `detailed_schedule`, `contraindications`, `adverse_effects`, `warnings`, `source_reference_url`, `source_review_date`, `image`, `is_featured`, `sort_order`, `views`, `is_active`, `created_at`, `updated_at`) VALUES ('3', 'Rotarix', '900000', '900000', '2', 'available', 'Vắc xin đường uống phòng bệnh tiêu chảy cấp do Rotavirus gây ra ở trẻ nhỏ.', 'Tiêu chảy cấp do Rotavirus', 'Tiêu chảy Rota', 'Trẻ em (6 tuần – 24 tuần)', 'Bỉ', 'GSK', '1.5ml', 'Chỉ dùng đường uống; không tiêm.', 'Hai liều từ 6 tuần tuổi, cách nhau ít nhất 4 tuần; hoàn tất trước 24 tuần tuổi.', 'Quá mẫn; tiền sử lồng ruột; dị tật tiêu hóa làm tăng nguy cơ lồng ruột; suy giảm miễn dịch kết hợp nặng.', 'Có thể gặp tiêu chảy hoặc kích thích; cần theo dõi dấu hiệu lồng ruột.', 'Hoãn khi sốt cấp nặng, tiêu chảy hoặc nôn; rửa tay kỹ sau thay tã.', 'https://extranet.who.int/prequal/sites/default/files/vwa_vaccine/fvp-p-62_rota-iquid_1dose_gsk_pi_tube-2024.pdf', '2026-08-10', '3-rotarix.jpg', '0', '3', '3', '1', '2026-08-07 07:17:38', '2026-08-12 15:46:56');
INSERT INTO `vaccines` (`id`, `name`, `price`, `sale_price`, `doses`, `stock_status`, `description`, `disease_prevention`, `category`, `age_group`, `origin`, `manufacturer`, `dosage`, `administration_route`, `detailed_schedule`, `contraindications`, `adverse_effects`, `warnings`, `source_reference_url`, `source_review_date`, `image`, `is_featured`, `sort_order`, `views`, `is_active`, `created_at`, `updated_at`) VALUES ('4', 'Rotavin', '490000', '490000', '2', 'available', 'Vắc xin uồng phòng tiêu chảy do Rotavirus sản xuất tại Việt Nam.', 'Tiêu chảy cấp do Rotavirus', 'Tiêu chảy Rota', 'Trẻ em (6 tuần – 24 tuần)', 'Việt Nam', 'POLYVAC', '2ml', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '4-rotavin.jpg', '0', '4', '0', '1', '2026-08-07 07:17:38', '2026-08-12 15:47:02');
INSERT INTO `vaccines` (`id`, `name`, `price`, `sale_price`, `doses`, `stock_status`, `description`, `disease_prevention`, `category`, `age_group`, `origin`, `manufacturer`, `dosage`, `administration_route`, `detailed_schedule`, `contraindications`, `adverse_effects`, `warnings`, `source_reference_url`, `source_review_date`, `image`, `is_featured`, `sort_order`, `views`, `is_active`, `created_at`, `updated_at`) VALUES ('5', 'BCG', '125000', '125000', '1', 'available', 'Vắc xin phòng bệnh lao cho trẻ sơ sinh càng sớm càng tốt sau khi sinh.', 'Bệnh Lao', 'Lao', 'Trẻ em sơ sinh (<1 tháng)', 'Việt Nam', 'IVAC', '0.1ml', 'Tiêm trong da; không tiêm dưới da hoặc vào mạch máu.', 'Một liều theo chương trình tiêm chủng và hướng dẫn sử dụng hiện hành; liều dùng phụ thuộc tuổi.', 'Đã nhiễm lao; sốt hoặc bệnh cấp; suy giảm miễn dịch, bệnh ác tính hoặc điều trị ức chế miễn dịch.', 'Có thể sốt nhẹ, nổi hạch hoặc áp-xe tại chỗ; nốt tiêm thường tiến triển thành sẹo nhỏ.', 'Phải tiêm đúng trong da; khám ngay nếu có dấu hiệu nhiễm BCG toàn thân hoặc viêm hạch mủ.', 'https://dav.gov.vn/bcg-n1146.html', '2026-08-10', '5-bcg.jpg', '0', '5', '2', '1', '2026-08-07 07:17:38', '2026-08-12 15:41:27');
