INSERT INTO `vaccines` (`id`, `name`, `price`, `sale_price`, `doses`, `stock_status`, `description`, `disease_prevention`, `category`, `age_group`, `origin`, `manufacturer`, `dosage`, `administration_route`, `detailed_schedule`, `contraindications`, `adverse_effects`, `warnings`, `source_reference_url`, `source_review_date`, `image`, `is_featured`, `sort_order`, `views`, `is_active`, `created_at`, `updated_at`) VALUES ('10', 'Prevenar 13', '1490000', '1490000', '3', 'available', 'Vắc xin phòng các bệnh xâm lấn do phế cầu khuẩn gây ra: Viêm phổi, viêm màng não, nhiễm trùng huyết.', 'Phế cầu 13 (Viêm phổi, viêm màng não)', 'Phế cầu', '6 tuần tuổi trở lên', 'Bỉ', 'Pfizer', '0.5ml', 'Tiêm bắp.', 'Số liều phụ thuộc tuổi, tiền sử tiêm và nguy cơ; trẻ nhỏ thường cần loạt cơ bản và liều nhắc.', 'Quá mẫn với hoạt chất, tá dược hoặc giải độc tố bạch hầu.', 'Đau, đỏ, sưng chỗ tiêm; sốt, quấy khóc, buồn ngủ hoặc giảm ăn.', 'Hoãn khi sốt cấp nặng; vắc xin không bảo vệ ngoài các týp huyết thanh có trong sản phẩm.', 'https://www.ema.europa.eu/en/documents/product-information/prevenar-13-epar-product-information_en.pdf', '2026-08-10', '10-prevenar-13.jpg', '0', '10', '2', '1', '2026-08-07 07:17:39', '2026-08-12 15:47:17');
INSERT INTO `vaccines` (`id`, `name`, `price`, `sale_price`, `doses`, `stock_status`, `description`, `disease_prevention`, `category`, `age_group`, `origin`, `manufacturer`, `dosage`, `administration_route`, `detailed_schedule`, `contraindications`, `adverse_effects`, `warnings`, `source_reference_url`, `source_review_date`, `image`, `is_featured`, `sort_order`, `views`, `is_active`, `created_at`, `updated_at`) VALUES ('11', 'Prevenar 20', '1750000', '1750000', '3', 'available', 'Vắc xin phế cầu 20 thế hệ mới bảo vệ diện rộng phòng 20 serotype phế cầu khuẩn.', 'Phế cầu 20 (Bảo vệ diện rộng)', 'Phế cầu', '6 tuần tuổi trở lên', 'Bỉ', 'Pfizer', '0.5ml', 'Tiêm bắp.', 'Người lớn thường dùng một liều; lịch trẻ em phụ thuộc tuổi và tiền sử tiêm.', 'Quá mẫn với hoạt chất, tá dược hoặc protein mang CRM197.', 'Đau, đỏ, sưng chỗ tiêm; mệt, đau cơ hoặc đau đầu; trẻ nhỏ có thể sốt và quấy khóc.', 'Hoãn khi sốt cấp nặng; thận trọng khi có rối loạn đông máu hoặc suy giảm miễn dịch.', 'https://www.ema.europa.eu/en/documents/product-information/prevenar-20-epar-product-information_en.pdf', '2026-08-10', '11-prevenar-20.jfif', '0', '11', '2', '1', '2026-08-07 07:17:39', '2026-08-12 15:47:21');
INSERT INTO `vaccines` (`id`, `name`, `price`, `sale_price`, `doses`, `stock_status`, `description`, `disease_prevention`, `category`, `age_group`, `origin`, `manufacturer`, `dosage`, `administration_route`, `detailed_schedule`, `contraindications`, `adverse_effects`, `warnings`, `source_reference_url`, `source_review_date`, `image`, `is_featured`, `sort_order`, `views`, `is_active`, `created_at`, `updated_at`) VALUES ('12', 'Influvac Tetra', '350000', '350000', '1', 'available', 'Vắc xin cúm tứ giá phòng 4 chủng virus cúm mùa phổ biến.', 'Cúm mùa tứ giá', 'Cúm mùa', '6 tháng tuổi trở lên', 'Hà Lan', 'Abbott', '0.5ml', 'Tiêm bắp hoặc tiêm dưới da sâu.', 'Từ 6 tháng tuổi: một liều mỗi mùa cúm; trẻ dưới 9 tuổi chưa từng tiêm cúm cần liều thứ hai sau ít nhất 4 tuần.', 'Quá mẫn với thành phần hoặc lượng tồn dư được nêu trong hướng dẫn sản phẩm; hoãn khi sốt hoặc nhiễm trùng cấp.', 'Đau chỗ tiêm, mệt hoặc đau đầu; trẻ nhỏ có thể sốt, quấy khóc hoặc giảm ăn.', 'Không tiêm vào mạch máu; thận trọng khi giảm tiểu cầu, rối loạn đông máu hoặc suy giảm miễn dịch.', 'https://extranet.who.int/prequal/sites/default/files/vwa_vaccine/FVP-P-460_InfluenzaQIV_1dose_Abbot_PI-NH2025-26.pdf', '2026-08-10', '12-influvac-tetra.jpg', '0', '12', '3', '1', '2026-08-07 07:17:39', '2026-08-12 15:47:24');
